import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const projectRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const leafletPackageRoot = resolve(projectRoot, 'node_modules/leaflet');
const leafletRoot = resolve(leafletPackageRoot, 'dist');
const outputPath = resolve(
  projectRoot,
  'src/features/map/leaflet-assets.generated.ts',
);

const javascript = readFileSync(resolve(leafletRoot, 'leaflet.js'), 'utf8')
  .replace(/\n\/\/# sourceMappingURL=.*$/u, '')
  .replace(/<\/script/giu, '<\\/script');
const css = readFileSync(resolve(leafletRoot, 'leaflet.css'), 'utf8').replace(
  /url\([^)]*\)/gu,
  'none',
);
const { version } = JSON.parse(
  readFileSync(resolve(leafletPackageRoot, 'package.json'), 'utf8'),
);

const output = `// Generated by scripts/generate-leaflet-assets.mjs from Leaflet ${version}.
// Leaflet is licensed under BSD-2-Clause. Do not edit this file manually.
export const LEAFLET_CSS = ${JSON.stringify(css)};

export const LEAFLET_JAVASCRIPT = ${JSON.stringify(javascript)};
`;

writeFileSync(outputPath, output);
